def tc(case_id: str, title: str, role: str, pre: str, steps: str, expected: str) -> dict:
    """Compact declaration for the current end-to-end manual suite."""
    return {
        "id": case_id,
        "title": title,
        "role": role,
        "pre": pre,
        "steps": steps.split(" | "),
        "expected": expected.split(" | "),
    }


