def main() -> None:
    doc = Document()
    section = doc.sections[0]
    section.top_margin = Cm(1.5)
    section.bottom_margin = Cm(1.5)
    section.left_margin = Cm(1.6)
    section.right_margin = Cm(1.6)

    normal = doc.styles["Normal"]
    normal.font.name = "Arial"
    normal._element.rPr.rFonts.set(qn("w:eastAsia"), "Arial")
    normal.font.size = Pt(10)
    for style_name in ("Title", "Heading 1", "Heading 2"):
        style = doc.styles[style_name]
        style.font.name = "Arial"
        style._element.rPr.rFonts.set(qn("w:eastAsia"), "Arial")
        style.font.color.rgb = RGBColor(31, 78, 121)

    title = doc.add_heading("BudgetBasket", 0)
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    subtitle = doc.add_paragraph("Полный план ручного функционального, ролевого и сквозного тестирования")
    subtitle.alignment = WD_ALIGN_PARAGRAPH.CENTER
    subtitle.runs[0].bold = True
    doc.add_paragraph("Версия документа: 2.0    Дата актуализации: 27.08.2026    Статус: для выполнения")

    doc.add_heading("Назначение и правила заполнения", level=1)
    doc.add_paragraph("Документ покрывает весь пользовательский функционал текущей версии BudgetBasket: авторизацию и роли, администрирование, НСИ, заявки и строки бюджета, файлы, реестр, полный маршрут согласования, чаты, историю, уведомления, дашборды, экспорты, адаптивность и ключевые проверки безопасности. Каждый тест выполняйте на подготовленном стенде. После выполнения отметьте статус, фактический результат и ссылку на дефект либо укажите «не требуются».")
    doc.add_paragraph("Рекомендуемые окружения: Google Chrome или Microsoft Edge актуальной версии; desktop 1440×900 и 1024×768; tablet 768×1024; mobile 375×667 и 320×568. Проверяйте также масштаб браузера 200%.")

    doc.add_heading("Критерии начала и завершения", level=1)
    doc.add_paragraph("Начало: стенд собран без ошибок, миграции применены, health-check успешны, тестовые роли и данные подготовлены. Завершение: выполнены все применимые тесты; нет открытых блокирующих и критических дефектов; дефекты высокой важности согласованы; итоговые суммы, статусы, история и права доступа проверены сквозным маршрутом.")

    doc.add_heading("Подготовка тестового стенда", level=1)
    preparation = [
        "Запустить стек: docker compose up -d --build.",
        "Проверить сервисы: GET /health, GET /health/db, Swagger /docs, SeaweedFS S3 и готовность file_guard.",
        "Использовать тестовые учётные записи: admin/admin, employee/employee, economist/economist, approver/approver, zgd/zgd.",
        "Подготовить две независимые ветки Департамент → ЦФО → Модуль, разные назначения ответственных и экономистов, статьи ДДС и инвест-проекты.",
        "Подготовить заявки минимум двух лет: доходные и расходные, разных статусов, с одинаковыми статьями в нескольких модулях и ЦФО.",
        "Подготовить безопасные PDF, PNG/JPG/GIF/WebP, DOCX, XLSX, ZIP и негативный набор: пустой, крупный, повреждённый, EXE, двойное расширение, MIME mismatch, macro/zip-slip/antivirus test file.",
        "Для проверки realtime открыть две независимые браузерные сессии; для проверки прав не переиспользовать токен другой роли.",
    ]
    for item in preparation:
        doc.add_paragraph(item, style="List Bullet")

    doc.add_heading("Параметры прогона", level=1)
    run_info = doc.add_table(rows=0, cols=2)
    run_info.style = "Table Grid"
    for label in ("Стенд / URL", "Версия / сборка", "Браузер и ОС", "Тестировщик", "Дата начала", "Дата завершения"):
        cells = run_info.add_row().cells
        set_cell_text(cells[0], label, True)
        set_cell_text(cells[1], "____________________________________________________________")
        shade(cells[0], "EAF2F8")

    doc.add_heading("Легенда статусов", level=1)
    legend = doc.add_table(rows=1, cols=2)
    legend.style = "Table Grid"
    for cell, text in zip(legend.rows[0].cells, ("Статус", "Значение")):
        set_cell_text(cell, text, True)
        shade(cell, "1F4E79")
        for run in cell.paragraphs[0].runs:
            run.font.color.rgb = RGBColor(255, 255, 255)
    for status, meaning in (("Пройден", "Фактический результат соответствует ожидаемому."), ("Не пройден", "Есть дефект; описать его и необходимую доработку."), ("Заблокирован", "Тест невозможно выполнить; указать причину."), ("Не применимо", "Сценарий не относится к текущему стенду; указать основание.")):
        cells = legend.add_row().cells
        set_cell_text(cells[0], status)
        set_cell_text(cells[1], meaning)

    grouped = [
        ("1. Стенд, авторизация и профиль", ("ENV-", "AUTH-", "PROFILE-")),
        ("2. Пользователи, оргструктура и НСИ", ("USR-", "ORG-", "CAT-")),
        ("3. Заявки, строки бюджета и файлы", ("REQ-", "LINE-", "FILE-", "SUBMIT-")),
        ("4. Реестр и проверка ответственным ЦФО", ("REG-", "CFO-")),
        ("5. Полный маршрут согласования", ("ECO-", "APR-", "ZGD-", "FLOW-", "ROUTE-")),
        ("6. Чаты, история и уведомления", ("CHAT-", "HIST-", "NOTE-")),
        ("7. Дашборды и экспорты", ("DASH-", "EXPORT-")),
        ("8. Интерфейс, устойчивость и безопасность", ("UI-", "SEC-")),
    ]
    all_tests = current_tests()
    for heading, prefixes in grouped:
        doc.add_page_break()
        doc.add_heading(heading, level=1)
        prefixes = (prefixes,) if isinstance(prefixes, str) else prefixes
        for test in (test for test in all_tests if test["id"].startswith(prefixes)):
            add_test(doc, test)

    doc.add_page_break()
    doc.add_heading("Итог выполнения", level=1)
    summary = doc.add_table(rows=5, cols=2)
    summary.style = "Table Grid"
    for row, label in zip(summary.rows, ("Всего тестов", "Пройдено", "Не пройдено", "Заблокировано", "Не применимо")):
        set_cell_text(row.cells[0], label, True)
        set_cell_text(row.cells[1], "")
        shade(row.cells[0], "EAF2F8")
    set_cell_text(summary.rows[0].cells[1], str(len(all_tests)), True)
    doc.add_paragraph("Общий вывод / перечень критичных доработок:")
    doc.add_paragraph("________________________________________________________________________________\n" * 5)
    doc.add_heading("Карточка дефекта", level=2)
    defect = doc.add_table(rows=0, cols=2)
    defect.style = "Table Grid"
    for label in ("ID теста", "Краткое название", "Приоритет / серьёзность", "Шаги воспроизведения", "Фактический результат", "Ожидаемый результат", "Вложения / ссылка", "Статус дефекта"):
        cells = defect.add_row().cells
        set_cell_text(cells[0], label, True)
        set_cell_text(cells[1], "____________________________________________________________")
        shade(cells[0], "EAF2F8")
    doc.add_paragraph("Тестировщик: ____________________    Дата: ______________    Подпись: ____________________")

    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    doc.save(OUTPUT)
    print(f"Created: {OUTPUT.resolve()}")


if __name__ == "__main__":
    main()
